def service_trace(jobs):
    capacity = len(jobs)
    if capacity == 0:
        capacity = 1
    queue = new_queue(capacity)
    for work in jobs:
        enqueue(queue, work)
    served = []
    finished = []
    steps = 0
    while queue["size"] > 0:
        work = dequeue(queue)
        served.append(work)
        steps = steps + 1
        if work > 1:
            enqueue(queue, work - 1)
        else:
            finished.append(steps)
    return {"served": served, "finished": finished}

